// Accept a campaign submission and normalize it for the pipeline.
// Expected fields: title, description, target_amount, and optionally
// campaign_id (generated here if the source system doesn't supply one).
const body = $input.first().json.body || $input.first().json;

const campaignId = body.campaign_id
  || 'camp-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 7);

return [{
  json: {
    campaign_id: campaignId,
    title: (body.title || '').toString().trim(),
    description: (body.description || '').toString().trim(),
    target_amount: Number(body.target_amount) || 0
  }
}];

// Build a Slack Block Kit message from the AI recommendation.
const r = $input.first().json;
const title = $('Normalize Campaign').first().json.title;

const icon = { APPROVE: ':white_check_mark:', REJECT: ':no_entry:', ESCALATE: ':mag:' }[r.recommended_action] || ':grey_question:';
const score = (typeof r.risk_score === 'number') ? r.risk_score.toFixed(2) : 'n/a';
const path = r.recommended_action === 'APPROVE' ? 'approve'
          : r.recommended_action === 'REJECT' ? 'reject' : 'escalate';

return [{
  json: {
    text: `${icon} Campaign ${r.campaign_id}: AI recommends ${r.recommended_action}`,
    blocks: [
      {
        type: 'header',
        text: { type: 'plain_text', text: `${icon} AI recommendation: ${r.recommended_action}` }
      },
      {
        type: 'section',
        fields: [
          { type: 'mrkdwn', text: `*Campaign*\n${r.campaign_id}` },
          { type: 'mrkdwn', text: `*Title*\n${title || '(none)'}` },
          { type: 'mrkdwn', text: `*Risk score*\n${score}  (${r.risk_category || 'n/a'})` },
          { type: 'mrkdwn', text: `*Signals*\n${r.hard_blocked ? 'hard rule block' : 'LLM assessment'}${r.consensus_used ? ' + consensus' : ''}, lang=${r.detected_language || '?'}` }
        ]
      },
      { type: 'section', text: { type: 'mrkdwn', text: `*Rationale*\n${r.rationale || '(none)'}` } },
      {
        type: 'context',
        elements: [{
          type: 'mrkdwn',
          text: `Recommendation only — a reviewer records the decision via \`POST /api/v1/campaigns/${r.campaign_id}/${path}\` (requires the TrustAndSafetyAdmin role).`
        }]
      }
    ]
  }
}];
